// Pure helpers for the pipeline view: turn a run's output lines (tracing.py's "[  12.3s] worker kind key=value ...")
// into events that carry no site value. What leaves here per event: the run clock, the worker's role, a keyed hash of
// its name, the event kind, and counts, flags and timings. Names, references, numbers read from the sites, prices and
// page text stay behind. No network here, so `node --test` covers it.

const crypto = require("node:crypto");

const LINE = /^\[\s*(\d+(?:\.\d+)?)s\] (\S+)\s+([a-z_]+)\s?(.*)$/;
const MODEL = /^\[model\] (\d{3}) ([\d.]+)s\b.*\bthinking (on|off)/;
// trace workers that are steps of the orchestrator, not a website session
const LOGICAL = new Set(["briefing", "plan", "choose", "materials", "verify", "select", "calc", "gaps", "orchestrator",
  "starts", "bid_flow", "result", "specification", "mails", "board", "submit"]);
const SITE_KIND = /^(start_|site_|waiting_for_site$|slow_page$)/; // only a website session emits these
const NUMBERS = ["seconds", "requests", "input_tokens", "output_tokens", "cached_tokens", "pages", "kept", "read",
  "checked", "views", "attempt", "followed", "pending", "seconds_left", "collected", "passes", "round", "rounds", "count"];
const FLAGS = ["matches", "qa_complete", "complete", "stopped", "ready", "early", "fallback", "at_positions", "mapped",
  "ok"];
const LISTS = ["requirements", "positions", "doubtful", "amendments", "records", "needs", "kinds", "facts", "problems",
  "chosen", "blank", "new_amendments", "gaps", "open", "withdrawn"];
const ERROR_CLASS = /^['"]([A-Za-z]+(?:Error|Exceeded|Behavior))\b/;

function endOfString(text, at) {
  const quote = text[at];
  for (let i = at + 1; i < text.length; i++) {
    if (text[i] === "\\") i++;
    else if (text[i] === quote) return i + 1;
  }
  return -1; // cut off, as in the run summary's shortened lines
}

// A Python list, dict or tuple starting at `at`: where it ends and how many items it holds; null when cut off.
function container(text, at) {
  let depth = 0, commas = 0, any = false;
  for (let i = at; i < text.length;) {
    const c = text[i];
    if (c === "'" || c === '"') {
      i = endOfString(text, i);
      if (i < 0) return null;
      any = true;
      continue;
    }
    if ("[{(".includes(c)) { if (depth) any = true; depth++; }
    else if ("]})".includes(c)) { if (!--depth) return { end: i + 1, count: any ? commas + 1 : 0 }; }
    else if (c === "," && depth === 1) commas++;
    else if (c !== " ") any = true;
    i++;
  }
  return null;
}

// The top-level key=value pairs of a trace line, in the form tracing.py prints them; stops at a cut-off value.
function fields(brief) {
  const found = {};
  const key = /([A-Za-z_][\w.-]*)=/y;
  for (let i = 0; i < brief.length;) {
    key.lastIndex = i;
    const match = key.exec(brief);
    if (!match) break;
    const at = key.lastIndex, c = brief[at];
    let end, value;
    if (c === "'" || c === '"') {
      end = endOfString(brief, at);
      if (end < 0) break;
      value = { type: "text", raw: brief.slice(at, end) };
    } else if (c && "[{(".includes(c)) {
      const inner = container(brief, at);
      if (!inner) break;
      end = inner.end;
      value = { type: "items", raw: brief.slice(at, end), count: inner.count };
    } else {
      end = brief.indexOf(" ", at);
      if (end < 0) end = brief.length;
      value = { type: "bare", raw: brief.slice(at, end) };
    }
    found[match[1]] = value;
    i = end;
    while (brief[i] === " ") i++;
  }
  return found;
}

function role(worker, kind) {
  const at = worker.indexOf(":");
  if (at < 0) return LOGICAL.has(worker) && !SITE_KIND.test(kind) ? worker : "site";
  const tag = worker.slice(at + 1);
  if (/^spec\d*$/.test(tag)) return "spec";
  if (/^tender\d*$/.test(tag)) return "tender";
  if (/^qa\d*$/.test(tag)) return "qa";
  if (/^mail\d+$/.test(tag)) return "mail";
  if (/^gap\d+$/.test(tag)) return "gap";
  return "erp"; // the ERP's tabs are named after what they look up
}

// Which ERP job a worker does, from the start of its goal (our own prompt text) or the events only one of them emits.
function erpJob(worker, kind, data) {
  if (worker.endsWith(":start")) return "gate";
  if (kind === "material_read" || kind === "material_failed" || kind === "read") return "material";
  const goal = kind === "start" && data.goal ? data.goal.raw.slice(1, 24) : "";
  if (goal.startsWith("Open the views")) return "material";
  if (goal.startsWith("List the")) return "search";
  return null;
}

const hashed = (secret, text) => crypto.createHmac("sha256", secret).update(text).digest("hex").slice(0, 10);

function event(text, secret, run) {
  const match = LINE.exec(text);
  if (!match) return null;
  const [, seconds, worker, kind, brief] = match;
  const data = fields(brief), n = {};
  for (const key of NUMBERS) if (data[key] && data[key].type === "bare" && /^-?\d+(\.\d+)?$/.test(data[key].raw)) n[key] = Number(data[key].raw);
  for (const key of FLAGS) if (data[key] && /^(True|False)$/.test(data[key].raw)) n[key] = data[key].raw === "True";
  for (const key of LISTS) if (data[key] && data[key].type === "items") n[key] = data[key].count;
  const out = { t: Number(seconds), w: hashed(secret, `${run} ${worker}`), r: role(worker, kind), k: kind, n };
  if (out.r === "erp") out.s = erpJob(worker, kind, data);
  if (kind === "state") { // starts.state: one website per key
    const states = Object.values(data).filter((value) => value.type === "text").map((value) => value.raw.slice(1, -1));
    for (const state of ["up", "starting", "down"]) n[state] = states.filter((value) => value === state).length;
  }
  if (data.answer) {
    n.decision = (/'decision': '(bid|no_bid)'/.exec(data.answer.raw) || [])[1] || null;
    n.priced = (data.answer.raw.match(/'unit_price': \d/g) || []).length;
  }
  if (data.record_kind) n.kid = hashed(secret, `${run} kind ${data.record_kind.raw}`);
  if (kind === "configure_position" && data.error) n.error = data.error.raw.length > 2;
  if (kind === "result" || (worker === "result" && kind === "done")) n.none = Boolean(data.result && data.result.raw === "None");
  const why = data.reason || data.error;
  if (why && ERROR_CLASS.test(why.raw)) n.why = ERROR_CLASS.exec(why.raw)[1];
  return out;
}

// lines: [{ t: milliseconds on the run clock, text }], oldest first (the platform keeps only the newest few hundred).
function sanitize(lines, secret, run) {
  const events = [], jobs = {}, model = { calls: 0, thinking: 0, errors: 0, last30: 0 };
  const newest = lines.length ? lines[lines.length - 1].t : 0;
  for (const line of lines) {
    const call = MODEL.exec(line.text);
    if (call) {
      model.calls++;
      if (call[3] === "on") model.thinking++;
      if (call[1] !== "200") model.errors++;
      if (line.t > newest - 30_000) model.last30++;
      continue;
    }
    const parsed = event(line.text, secret, run);
    if (!parsed) continue;
    if (parsed.s) jobs[parsed.w] = parsed.s;
    events.push(parsed);
  }
  for (const parsed of events) if (parsed.r === "erp") parsed.s = parsed.s || jobs[parsed.w] || null;
  return { events, model };
}

module.exports = { fields, container, role, event, sanitize };

// GET /api/pipeline?run=run_...: one run's live state and its trace events, reduced to counts and timings.
// The output lines are read with the ATIRA_TOKEN secret and never leave this function; see _pipeline.js for what does.

const { sanitize } = require("./_pipeline.js");

const API = "https://ehl-challenge.atira.ai";
const LIVE_MS = 2_500; // every viewer of a live run within this window shares one platform read
const DONE_MS = 300_000;
const KEPT = 30; // runs remembered by a warm function
const cache = new Map();

async function read(path, token) {
  const answer = await fetch(`${API}${path}`, {
    headers: { "x-api-key": token, "User-Agent": "error404ai-monitor/1.0" },
    signal: AbortSignal.timeout(20_000),
  });
  if (!answer.ok) throw new Error(`platform answered ${answer.status}`);
  return answer.json();
}

async function lines(run, token) {
  const all = [];
  for (let after = null, page = 0; page < 4; page++) {
    const body = await read(`/v1/runs/${run}/logs/query?from=0&stream=stdout&limit=1000${after ? `&after=${encodeURIComponent(after)}` : ""}`, token);
    all.push(...(body.lines || []));
    after = body.next;
    if (!after) break;
  }
  return all;
}

async function pipeline(run, token, now) {
  const [feed, output] = await Promise.all([read(`/v1/runs/${run}/feed`, token), lines(run, token)]);
  const { events, model } = sanitize(output, token, run);
  return {
    updated: now,
    run,
    phase: feed.phase,
    phaseTimes: feed.phase_times || {},
    status: feed.status,
    failure: feed.failure_class || null,
    started: feed.started_at || null,
    finished: feed.finished_at || null,
    now: feed.now || now,
    calls: feed.calls || 0,
    cost: (feed.cost_micro_usd || 0) / 1e6,
    browsers: feed.browsers || null,
    queue: feed.queue_position || null,
    model,
    events,
  };
}

module.exports = async (request, response) => {
  const run = new URL(request.url, "http://monitor").searchParams.get("run") || "";
  if (!/^run_[0-9a-f]{8,32}$/.test(run)) return response.status(400).json({ error: "run: expected a run id" });
  const token = process.env.ATIRA_TOKEN;
  if (!token) return response.status(500).json({ error: "ATIRA_TOKEN is not set on this deployment" });
  const now = Date.now(), held = cache.get(run);
  if (held && now - held.updated < (held.phase === "done" ? DONE_MS : LIVE_MS)) {
    response.setHeader("Cache-Control", "public, s-maxage=2, stale-while-revalidate=5");
    return response.status(200).json(held);
  }
  try {
    const state = await pipeline(run, token, now);
    cache.delete(run);
    cache.set(run, state);
    for (const old of cache.keys()) if (cache.size > KEPT) cache.delete(old);
    response.setHeader("Cache-Control", "public, s-maxage=2, stale-while-revalidate=5");
    return response.status(200).json(state);
  } catch (error) {
    if (held) return response.status(200).json({ ...held, stale: String(error.message || error) });
    return response.status(502).json({ error: String(error.message || error) });
  }
};

// The pipeline view's model, shared by the page and `node --test`: merge the events of successive reads of one run
// and reduce them to stages (waiting, running, done), what the run holds so far, and a line per thing that happened.
// The platform keeps only a run's newest few hundred output lines, so a page that stays open merges every read; one
// opened late marks the stages it missed as "past" once a later stage shows life.
(function (root, factory) {
  if (typeof module === "object" && module.exports) module.exports = factory();
  else root.Pipeline = factory();
})(this, function () {
  const COLUMNS = [
    ["Start", ["sandbox", "signin"]],
    ["Understand", ["brief", "plan"]],
    ["Read", ["spec", "tender", "qa", "mail", "early"]],
    ["Match", ["search", "material", "choose"]],
    ["Decide", ["verify", "gaps", "calc"]],
    ["Bid", ["enter", "review", "tan", "sign", "score"]],
  ];
  const TITLES = {
    sandbox: "Sandbox", signin: "Site sign-ins", brief: "Read the brief", plan: "Plan the research",
    spec: "Specification", tender: "Tender positions", qa: "Bidder Q&A", mail: "Mail records", early: "Bid form, early pass",
    search: "ERP search", material: "ERP material records", choose: "Choose materials",
    verify: "Verify the findings", gaps: "Fill the gaps", calc: "Calculate the bid",
    enter: "Enter the positions", review: "Check the review page", tan: "Signing TAN", sign: "Sign and submit", score: "Score",
  };
  const EDGES = [["sandbox", "signin"], ["sandbox", "brief"], ["brief", "plan"], ["plan", "spec"], ["plan", "tender"],
    ["plan", "qa"], ["plan", "mail"], ["brief", "early"], ["spec", "search"], ["search", "material"],
    ["material", "choose"], ["tender", "verify"], ["qa", "verify"], ["mail", "verify"], ["choose", "verify"],
    ["verify", "gaps"], ["gaps", "calc"], ["calc", "enter"], ["early", "enter"], ["enter", "review"],
    ["review", "tan"], ["tan", "sign"], ["sign", "score"]];
  const OPTIONAL = ["gaps", "early"]; // a run may rightly skip these
  const FINAL = ["submitted", "scored", "failed", "timed_out"];
  const WORKER = { spec: "Specification reader", tender: "Tender reader", qa: "Q&A reader", mail: "Mail search",
    gap: "Gap worker", gate: "ERP sign-in", search: "ERP search", material: "ERP material reader" };

  const key = (event) => `${event.t}|${event.w}|${event.k}`;
  const plural = (count, one, many) => `${count} ${count === 1 ? one : many || one + "s"}`;
  const known = (value) => value != null;

  // Add one read's events to what earlier reads gave; the fuller copy of an event wins (the run summary shortens lines).
  function merge(held, events) {
    for (const event of events || []) {
      const id = key(event), before = held.get(id);
      held.set(id, before ? { ...event, ...before, n: { ...event.n, ...before.n }, s: before.s || event.s } : event);
    }
    return held;
  }

  function reduce(list, meta) {
    meta = meta || {};
    const events = [...list].sort((a, b) => a.t - b.t);
    const stages = {}, ticker = [], jobs = {};
    for (const [, ids] of COLUMNS) for (const id of ids) stages[id] = { id, title: TITLES[id], state: "wait", from: null, to: null, detail: "", active: 0 };
    const begin = (id, t) => { const s = stages[id]; if (s.from == null) s.from = t; if (s.state !== "run") { s.state = "run"; s.to = null; } };
    const end = (id, t, state) => { const s = stages[id]; if (s.from == null) s.from = t; s.to = t; s.state = state || "done"; };
    const say = (t, text, tone) => {
      const last = ticker[ticker.length - 1];
      if (last && last.text === text) { last.times++; last.t = t; } else ticker.push({ t, text, tone: tone || "", times: 1 });
    };
    const sets = () => ({ started: new Set(), done: new Set() });
    const c = { up: new Set(), sites: null, down: 0, needs: null, requirements: null, positions: null, amendments: null,
      qaComplete: null, workers: { spec: sets(), tender: sets(), qa: sets(), mail: sets(), search: sets(), material: sets() },
      read: 0, views: 0, unread: 0, planned: null, kinds: new Set(), kept: 0, mailFailed: 0, chosen: 0, selected: null,
      checked: null, doubtful: null, disputed: false, gaps: 0, filled: 0, open: null, rounds: 0, calcPositions: null,
      decision: null, priced: null, fallback: false, configured: 0, byModel: 0, matches: null, tans: 0, problems: 0,
      refused: 0, requests: 0, tokens: 0, seen: events.length };
    let handover = null, bid = null, tanWorker = null, orchestrated = null, result = null;

    for (const e of events) {
      const n = e.n || {}, t = e.t;
      if (e.s) jobs[e.w] = e.s;
      const job = e.r === "erp" ? e.s || jobs[e.w] || "search" : e.r;
      if (e.k === "problem") { c.problems++; say(t, "Problem noted on the findings board", "warn"); continue; }
      if (/_refused$/.test(e.k)) { c.refused++; say(t, "Refused a value that is on no page the worker saw", "warn"); continue; }
      if (e.k === "done" && known(n.requests)) { c.requests += n.requests; c.tokens += (n.input_tokens || 0) + (n.output_tokens || 0); }
      const tally = c.workers[job === "gate" ? "search" : job];
      if (tally && (e.k === "start" || e.k === "done" || e.k === "stopped")) {
        if (e.k === "start") { tally.started.add(e.w); tally.done.delete(e.w); begin(job === "gate" ? "search" : job, t); say(t, `${WORKER[job]} started`); }
        else {
          tally.done.add(e.w);
          if (e.k === "stopped") say(t, `${WORKER[job]} stopped${n.why ? ` (${n.why})` : ""}`, "warn");
          else if (job !== "material") say(t, `${WORKER[job]} finished${known(n.requests) ? ` · ${plural(n.requests, "model call")}` : ""}`);
        }
      }
      switch (e.k) {
        case "start_ok":
          if (e.r === "site") { c.up.add(e.w); begin("signin", t); say(t, `Signed in to a website${n.attempt > 1 ? ` on attempt ${n.attempt}` : ""}`); }
          break;
        case "start_failed":
          if (e.r === "site") begin("signin", t);
          say(t, "A website did not open, trying again", "warn");
          break;
        case "state":
          if (e.r === "starts") { c.sites = (n.up || 0) + (n.starting || 0) + (n.down || 0); c.down = (n.down || 0) + (n.starting || 0); c.stateAt = t; }
          break;
        case "slow_page": say(t, "Slow page, waiting for it", "warn"); break;
        case "plan":
          if (known(n.kinds)) { c.planned = n.kinds; begin("mail", t); say(t, `Mail search planned: ${plural(n.kinds, "record kind")}`); }
          break;
        case "mail_plan": if (known(n.kinds)) c.planned = Math.max(c.planned || 0, n.kinds); break;
        case "spec_done":
          end("spec", t); c.requirements = n.requirements ?? c.requirements;
          say(t, `Specification read${known(n.requirements) ? `: ${plural(n.requirements, "requirement")}` : ""}`, "go");
          break;
        case "tender_positions":
          c.positions = n.positions ?? c.positions;
          say(t, `Bill of quantities read${known(n.positions) ? `: ${plural(n.positions, "position")}` : ""}`);
          break;
        case "tender_qa":
          end("qa", t, n.complete === false ? "warn" : "done"); c.qaComplete = n.complete ?? c.qaComplete; c.amendments = n.amendments ?? c.amendments;
          say(t, `Bidder Q&A read${n.complete === false ? ", not to its end" : " to its end"}`, n.complete === false ? "warn" : "go");
          break;
        case "qa_incomplete": c.qaComplete = false; break;
        case "tender_facts":
          end("tender", t); c.positions = n.positions ?? c.positions; c.amendments = n.amendments ?? c.amendments;
          if (known(n.qa_complete)) { c.qaComplete = n.qa_complete; end("qa", t, n.qa_complete ? "done" : "warn"); }
          say(t, `Tender facts resolved${known(n.positions) ? `: ${plural(n.positions, "position")}` : ""}${n.amendments ? `, ${plural(n.amendments, "amendment")}` : ""}`, "go");
          break;
        case "material_read": c.read++; c.views += n.views || 0; say(t, `ERP material record read${n.views ? ` · ${plural(n.views, "view")}` : ""}`); break;
        case "material_failed": c.unread++; say(t, "An ERP material record could not be read", "warn"); break;
        case "mail_kind":
          c.kinds.add(n.kid || key(e)); c.kept += n.kept || 0;
          say(t, `Mail record kind read · ${plural(n.kept || 0, "message")} kept`, n.kept ? "go" : "warn");
          break;
        case "mail_kind_failed": case "mail_search_failed": c.mailFailed++; say(t, "A mail search failed", "warn"); break;
        case "material":
          if (e.r === "choose") { c.chosen++; begin("choose", t); say(t, "Material chosen for a requirement"); }
          break;
        case "decision_disputed": c.disputed = true; say(t, "Verifier disputes the bid decision", "warn"); break;
        case "no_bid_overturned": say(t, "No-bid overturned after a second look", "warn"); break;
        case "gap": c.gaps++; say(t, "Gap noted in the findings"); break;
        case "gap_round": c.rounds = Math.max(c.rounds, n.round || c.rounds + 1); begin("gaps", t); say(t, "Gap round finished"); break;
        case "gap_filled": c.filled++; begin("gaps", t); say(t, "Gap filled", "go"); break;
        case "gap_open": c.open = n.gaps ?? c.open; break;
        case "gap_no_time": c.open = n.open ?? c.open; say(t, "No time left for the open gaps", "warn"); break;
        case "input":
          if (e.r === "calc") { begin("calc", t); c.calcPositions = n.positions ?? c.calcPositions; }
          break;
        case "answer":
          end("calc", t, n.fallback ? "warn" : "done");
          c.decision = n.decision || c.decision; c.priced = n.priced ?? c.priced; c.fallback = Boolean(n.fallback);
          say(t, `Answer calculated${c.decision ? `: ${c.decision}` : ""}${c.priced ? `, ${plural(c.priced, "position")} priced` : ""}`, "go");
          break;
        case "prepared":
          end("early", t, n.at_positions === false ? "warn" : "done");
          say(t, n.at_positions === false ? "Early form pass stopped short of the positions" : "Bidder data entered, form waits at the positions", n.at_positions === false ? "warn" : "go");
          break;
        case "session_lost": say(t, "Portal session lost, the form is prepared again", "warn"); break;
        case "handover":
          handover = t;
          if (stages.early.state === "run") end("early", t, n.ready === false ? "warn" : "done");
          begin("enter", t); say(t, "Answer handed to the bid form");
          break;
        case "form_budget": bid = e.w; begin("enter", t); break;
        case "configure_position":
          c.configured++; if (n.error) c.byModel++;
          begin("enter", t); say(t, n.error ? "Position configured, one choice left to the model" : "Position configured in the bid form");
          break;
        case "summary_check":
          bid = bid || e.w; c.matches = n.matches ?? null;
          end("enter", t); end("review", t, n.matches === false ? "warn" : "done"); begin("sign", t);
          say(t, n.matches === false ? "Review page differs from the answer" : "Review page matches the answer", n.matches === false ? "warn" : "go");
          break;
        case "last_chance": begin("sign", t); say(t, "Last-chance signing pass", "warn"); break;
        case "crashed": say(t, "Bid form pass crashed, signing what is on screen", "warn"); break;
        case "done": case "start": case "stopped":
          if (e.r === "briefing" && e.k === "done") { end("brief", t); say(t, "Brief read", "go"); }
