      ["Q&A amendments", c.amendments, "scoped changes that apply by the scenario date"],
      ["ERP material records", c.read || null, `status, stock, lead time, price scales${c.views ? ` (${plural(c.views, "view")} read)` : ""}`],
      ["Mail records", c.kept || null, `${c.kinds.size ? plural(c.kinds.size, "record kind") + ": " : ""}latest valid message per key and sender`],
      ["Chosen materials", c.selected ?? (c.chosen || null), "one exactly matching active material per requirement"],
      ["Facts verified", c.checked, known(c.doubtful) ? `${c.doubtful} sent back as doubtful` : "each fact needs a quote from a page"],
      ["Gaps", c.gaps || null, `${c.filled} filled${c.open ? `, ${c.open} still open` : ""}`],
      ["Problems", c.problems || null, "noted on the findings board for the calculation"],
      ["Values refused", c.refused || null, "returned by the model but on no page it had seen"],
      ["Answer", c.decision ? `${c.decision === "no_bid" ? "no bid" : "bid"}${c.priced ? `, ${c.priced} priced` : ""}` : null, "what the bid form is filled from"],
    ].map(([label, value, note]) => ({ label, value: known(value) ? String(value) : null, note }));

    return { columns: COLUMNS.map(([title, ids]) => ({ title, stages: ids.map((id) => stages[id]) })), stages, edges: EDGES,
      store, ticker: ticker.reverse(), clock, live, counts: { events: c.seen, requests: c.requests, tokens: c.tokens } };
  }

  return { merge, reduce, COLUMNS, EDGES };
